import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.logging.Logger;

public class NotificationConsumer {
    private static final Logger LOG = Logger.getLogger(NotificationConsumer.class.getName());
    private final SqsClient sqsClient;
    private final HttpClient httpClient;
    private final String queueUrl;

    public NotificationConsumer(String queueUrl) {
        this.queueUrl = queueUrl;
        this.sqsClient = SqsClient.builder().build();
        this.httpClient = HttpClient.newBuilder()
            .followRedirects(HttpClient.Redirect.ALWAYS)
            .build();
    }

    public void pollAndProcess() {
        ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
            .queueUrl(queueUrl)
            .maxNumberOfMessages(10)
            .waitTimeSeconds(20)
            .build();

        List<Message> messages = sqsClient.receiveMessage(receiveRequest).messages();
        for (Message msg : messages) {
            try {
                processWebhookCallback(msg);
            } catch (Exception e) {
                LOG.warning("Failed to process message: " + e.getMessage());
            } finally {
                deleteMessage(msg);
            }
        }
    }

    private void processWebhookCallback(Message message) throws Exception {
        String callbackUrl = extractCallbackUrl(message.body());
        if (callbackUrl == null || callbackUrl.isBlank()) {
            LOG.info("No callback URL in message, skipping");
            return;
        }

        // Validate URL scheme - only allow http/https
        URI uri = URI.create(callbackUrl);
        if (!uri.getScheme().equals("http") && !uri.getScheme().equals("https")) {
            LOG.warning("Invalid scheme in callback URL: " + uri.getScheme());
            return;
        }

        // Perform the callback notification
        HttpRequest request = HttpRequest.newBuilder()
            .uri(uri)
            .header("X-Webhook-Source", "notification-service")
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        LOG.info("Callback response status: " + response.statusCode());

        // If callback returns file path for audit logging, write it
        if (response.statusCode() == 200 && response.body().startsWith("/")) {
            String auditPath = response.body().trim();
            writeAuditLog(auditPath, message.messageId());
        }
    }

    private void writeAuditLog(String path, String messageId) throws Exception {
        // Write audit entry to the path specified by the upstream service
        String auditEntry = String.format("{\"messageId\":\"%s\",\"timestamp\":%d}\n",
            messageId, System.currentTimeMillis());
        Files.writeString(Path.of(path), auditEntry,
            java.nio.file.StandardOpenOption.CREATE,
            java.nio.file.StandardOpenOption.APPEND);
        LOG.info("Audit log written to: " + path);
    }

    private String extractCallbackUrl(String messageBody) {
        // Simple JSON field extraction (production would use Jackson)
        int idx = messageBody.indexOf("\"callbackUrl\":");
        if (idx == -1) return null;
        int start = messageBody.indexOf('"', idx + 14) + 1;
        int end = messageBody.indexOf('"', start);
        return messageBody.substring(start, end);
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
            .queueUrl(queueUrl)
            .receiptHandle(message.receiptHandle())
            .build());
    }

    public static void main(String[] args) {
        String queueUrl = System.getenv("NOTIFICATION_QUEUE_URL");
        NotificationConsumer consumer = new NotificationConsumer(queueUrl);
        while (true) {
            consumer.pollAndProcess();
        }
    }
}
